INSERT INTO "library_manuals" ("discipline", "title", "specialty", "course", "semester", "authors", "annotation", "status", "draft", "published", "draft_changed", "updated_by", "created_at", "updated_at", "published_at")
SELECT 'Сестринское дело', 'Дыхание: конспект по трём учебникам', 'Сестринское дело', 0, 0, 'Кафедра сестринского дела с курсом социальных дисциплин', 'Конспект по органам дыхания по пособию «Общий уход за больными в терапевтической клинике» и учебникам педиатрии Запруднова — Григорьева и Ежовой: АФО органов дыхания у детей, частота дыхания по возрасту, физиология и наблюдение, одышка, удушье, кашель, мокрота, кровохарканье, плевральная пункция, сбор мокроты, уход за детьми. С методическими указаниями, алгоритмами и самоконтролем.', 2, j, j, false, 'seed', now(), now(), now()
FROM (SELECT $json${"sections":[{"id":"nursing_resp1-s01","title":"Методические указания","blocks":[{"id":"nursing_resp1-001","text":{"text":"Методичка — для самостоятельной подготовки по теме «Сестринский уход при заболеваниях органов дыхания». Материал трёх учебников сведён по темам. Оксигенотерапия вынесена в отдельную методичку «Оксигенотерапия: конспект по трём учебникам»."}},{"id":"nursing_resp1-002","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Главное — методика","text":"Медсестру оценивают по тому, **как она выполняет манипуляцию**. Алгоритмы — помощь при удушье, постуральный дренаж, ассистирование при плевральной пункции — вынесены в карточки с шагами. Подробный разбор с оснащением, обоснованием шагов, ошибками и задачами — в методичке «Методика наблюдения и ухода при заболеваниях органов дыхания. Оксигенотерапия» этой же кафедры."}},{"id":"nursing_resp1-003","heading":{"text":"Цели изучения темы","level":2}},{"id":"nursing_resp1-004","text":{"text":"**Знать:**\n- АФО органов дыхания у детей и чем они опасны;\n- частоту дыхания по возрасту и у взрослого, виды одышки и патологические типы дыхания;\n- виды кашля и мокроты, признаки лёгочного кровотечения и его отличия от желудочного."}},{"id":"nursing_resp1-005","text":{"text":"**Уметь:**\n- подсчитать ЧДД у взрослого и ребёнка и записать в температурный лист;\n- оказать помощь при приступе удушья, обучить пользованию карманным ингалятором;\n- провести постуральный дренаж, собрать мокроту на исследование;\n- оказать помощь при кровохарканье;\n- подготовить всё и ассистировать врачу при плевральной пункции."}},{"id":"nursing_resp1-006","heading":{"text":"Как работать с методичкой","level":2}},{"id":"nursing_resp1-007","checklist":{"title":"Порядок подготовки к занятию","ordered":true,"steps":["Прочитать тему целиком и выписать незнакомые термины.","Выучить ЧДД по возрасту и соотношение ЧДД : ЧСС.","Выучить алгоритмы: помощь при удушье, постуральный дренаж, плевральная пункция.","Отработать в паре подсчёт ЧДД незаметно для «пациента» и технику ингалятора.","Пройти самоконтроль в конце методички."]}},{"id":"nursing_resp1-008","heading":{"text":"Источники","level":2}},{"id":"nursing_resp1-009","text":{"text":"- Общий уход за больными в терапевтической клинике (учебное пособие; авторы в файле не указаны) — с. 111 (плевральная пункция), 119 (исследование мокроты), 143–153 (наблюдение и уход при болезнях органов дыхания).\n- Запруднов А.М., Григорьев К.И. Педиатрия с детскими инфекциями. — 2011. — с. 50–52 (АФО дыхательной системы), 242–245 (уход за детьми с болезнями органов дыхания).\n- Ежова Н.В. и др. Педиатрия. — 2014. — с. 254–257 (АФО органов дыхания)."}}]},{"id":"nursing_resp1-s02","title":"1. АФО органов дыхания у детей","blocks":[{"id":"nursing_resp1-010","text":{"text":"Органы дыхания к рождению морфологически несовершенны; формирование заканчивается к 7 годам, функция внешнего дыхания становится как у взрослых только в старшем школьном возрасте. Верхние дыхательные пути — нос, глотка, гортань; нижние — трахея и бронхи; газообмен — в лёгких."}},{"id":"nursing_resp1-011","text":{"text":"**Общие особенности:** тонкая ранимая слизистая; слабо развитые железы; мало IgA и сурфактанта; рыхлый подслизистый слой, богатый капиллярами; мягкий хрящевой каркас; мало эластической ткани."}},{"id":"nursing_resp1-012","table":{"caption":"","header":true,"rows":[{"cells":["Отдел","Особенности","Чем опасно"]},{"cells":["Нос","Мал, ходы узкие, раковины толстые; нижний носовой ход формируется к 4 годам; новорождённый дышит только носом (большой язык); воздух согревается до 37 °C и увлажняется до 100%; пещеристая ткань слабая","Даже лёгкий насморк → отёк, затруднение сосания, одышка; носовые кровотечения редки"]},{"cells":["Пазухи","Решётчатая и гайморова развиты слабо, лобная и основная отсутствуют; слёзно-носовой проток широкий","Инфекция из носа в конъюнктиву"]},{"cells":["Евстахиева труба","Короткая, широкая, горизонтальная","Отит при рините"]},{"cells":["Надгортанник","Мягкий, неплотно закрывает трахею","Аспирация при рвоте и срыгивании, стридор"]},{"cells":["Гортань","Выше, чем у взрослых; воронкообразная; диаметр подсвязочного пространства 4 мм у новорождённого, 1 см к 14 годам; хрящи нежные, голосовая щель узкая","Стеноз (круп) даже при небольшом воспалении"]},{"cells":["Трахея","Относительно широкая, подвижная, хрящи мягкие","Спадение на выдохе — врождённый стридор (проходит к 2 годам)"]},{"cells":["Бронхи","Узкие, хрящи мягкие; у малышей угол отхождения одинаковый, с возрастом правый — продолжение трахеи; слабое самоочищение (мукоцилиарный клиренс, кашлевой рефлекс)","Инородные тела чаще в правом бронхе; закупорка слизью → ателектазы; бронхоспазм, астма"]},{"cells":["Лёгкие","Мало эластической ткани, полнокровны, маловоздушны; альвеолы доспевают до взрослого возраста; дефицит сурфактанта","Ателектазы (чаще в задненижних отделах), эмфизема, застой; разрыв паренхимы при нарушении техники ИВЛ"]},{"cells":["Плевра","Толстая, растяжимая, париетальный листок слабо фиксирован","Выпот смещает средостение"]},{"cells":["Диафрагма, грудная клетка","Диафрагма высоко, сокращения слабые; дыхательные мышцы слабые; грудная клетка податлива","Метеоризм и большая печень ухудшают вентиляцию; втяжение межреберий"]},{"cells":["Миндалины","У новорождённых не сформированы; после года гиперплазия, созревают к 4–5 годам","Аденоиды нарушают носовое дыхание"]}]}},{"id":"nursing_resp1-013","heading":{"text":"Дыхание по возрасту","level":2}},{"id":"nursing_resp1-014","table":{"caption":"","header":true,"rows":[{"cells":["Возраст","ЧДД в минуту","МОД на 1 кг, мл"]},{"cells":["Новорождённый","40–60","180–200"]},{"cells":["1–12 мес","30–45","190–230"]},{"cells":["1–3 года","25–35","200–220"]},{"cells":["4–6 лет","23–25","180–200"]},{"cells":["7–11 лет","18–23","150–180"]},{"cells":["12–15 лет","17–19","100–120"]},{"cells":["Взрослый","15–16","—"]}]}},{"id":"nursing_resp1-015","text":{"text":"- Дыхание частое и поверхностное: потребность в кислороде покрывается частотой, а не глубиной. 40–60 у новорождённого — «физиологическая одышка».\n- **ЧДД : ЧСС** — у новорождённых 1 : (2,5–3), у детей 1 : (3,5–4), у взрослых 1 : 4.\n- **Аритмия дыхания** в первые 2–3 недели (дыхательный центр созревает на 1-м году): неправильные паузы, вдох короче выдоха, кратковременные апноэ 10–30 с.\n- **Тип дыхания:** у малышей брюшной (диафрагмальный); в 2 года смешанный; в 3–4 года преобладает грудной; половые различия с 7–14 лет — у мальчиков брюшной, у девочек грудной.\n- **Первый вдох** — раздражение дыхательного центра гипоксией, гиперкапнией и ацидозом после прекращения плацентарного кровообращения.\n- **Как считать:** лучше во сне — рука на животе или фонендоскоп у носа. Исследование функции: ЧДД в покое и при нагрузке, экскурсия грудной клетки, газы крови и КЩС, спирометрия старше 5 лет (ЖЕЛ, ОФВ₁), **пикфлоуметрия**."}}]},{"id":"nursing_resp1-s03","title":"2. Физиология дыхания и наблюдение (взрослые)","blocks":[{"id":"nursing_resp1-016","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Подсчёт ЧДД — ежедневная манипуляция медсестры: **незаметно для больного**, рука как для пульса, запись в температурный лист **синими точками**. У детей — лучше во сне, рукой на животе или фонендоскопом у носа; оценка — по возрастной норме."}},{"id":"nursing_resp1-017","text":{"text":"- Функции: снабжение кислородом, выведение CO₂, участие в обмене веществ. Внешнее дыхание — в альвеолах (> 800 млн, диаметр 0,2–0,3 мм, площадь ~100 м²); 1–2% газообмена — через кожу и ЖКТ.\n- Дыхательный центр — продолговатый мозг (дно IV желудочка); раздражитель — повышение CO₂ и кислых продуктов в крови; гипоксия мозга угнетает центр. **Вдох активный** (сокращение мышц, диафрагма опускается), **выдох пассивный**.\n- **ЧДД взрослого 16–20 в минуту**, дыхательный объём ~500 см³. Учащается при нагрузке, волнении; урежается во сне и лёжа.\n- **Подсчёт ЧДД — незаметно для больного**: взять руку как для пульса и считать движения грудной клетки. Ежедневно отмечать в температурном листе **синими точками** (кривая дыхания).\n- Типы дыхания: грудной (чаще у женщин), брюшной (чаще у мужчин), смешанный (чаще у пожилых)."}}]},{"id":"nursing_resp1-s04","title":"3. Симптомы и уход","blocks":[{"id":"nursing_resp1-018","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Главное для практики: положение пациента (при удушье — полусидя, при кровохарканье — полусидя с наклоном **в больную сторону**, при боли от плевры — **на больном боку**), алгоритм помощи при удушье, техника карманного ингалятора, постуральный дренаж, сбор мокроты и ассистирование при плевральной пункции."}},{"id":"nursing_resp1-019","heading":{"text":"Одышка","level":2}},{"id":"nursing_resp1-020","text":{"text":"Одышка (диспноэ) — нарушение частоты, ритма и глубины дыхания с ощущением нехватки воздуха; бывает лёгочной, сердечной, неврогенной."}},{"id":"nursing_resp1-021","table":{"caption":"","header":true,"rows":[{"cells":["Признак","Вид","Что это"]},{"cells":["Частота","Тахипноэ","> 20 в минуту, поверхностное: пневмония, лихорадка, анемия; при истерии до 60–80 («дыхание загнанного зверя»)"]},{"cells":["Частота","Брадипноэ","< 16 в минуту: поражение мозга, тяжёлая гипоксия, ацидоз (диабетическая кома)"]},{"cells":["Фаза","Инспираторная / экспираторная / смешанная","Затруднён вдох / выдох / обе фазы"]},{"cells":["Ритм","Чейна–Стокса","После паузы дыхание нарастает по глубине и частоте, затем убывает; пауза до 30 с"]},{"cells":["Ритм","Биота","Равномерные глубокие дыхания чередуются с паузами до 30 с"]},{"cells":["Ритм","Куссмауля","Глубокое редкое шумное дыхание; глубокая кома"]}]}},{"id":"nursing_resp1-022","heading":{"text":"Удушье","level":2}},{"id":"nursing_resp1-023","text":{"text":"Удушье (астма) — острый приступ одышки: бронхиальная астма (спазм бронхов) или сердечная (застой в малом круге). Немедленно сообщить врачу и:"}},{"id":"nursing_resp1-025","checklist":{"title":"Алгоритм помощи при приступе удушья","ordered":true,"steps":["Создать покой, успокоить больного и окружающих.","Придать возвышенное (полусидячее) положение.","Освободить от стесняющей одежды и тяжёлых одеял.","Открыть форточку.","По назначению — карманный ингалятор, при дыхательной недостаточности — оксигенотерапия (см. отдельный конспект)."]}},{"id":"nursing_resp1-026","text":{"text":"**Карманный ингалятор:** снять колпачок → перевернуть баллончик дном вверх и встряхнуть → глубокий выдох → обхватить мундштук губами, глубокий вдох с одновременным нажатием на клапан → задержать дыхание на несколько секунд → вынуть мундштук, медленный выдох. Число доз определяет врач; после глюкокортикоидов — **прополоскать рот** (профилактика кандидоза)."}},{"id":"nursing_resp1-027","heading":{"text":"Кашель","level":2}},{"id":"nursing_resp1-028","text":{"text":"- Рефлекс на раздражение рецепторов дыхательных путей и плевры; очищает дыхательные пути. Причины: воспаление (ларингит, бронхит, пневмония, астма), аллергены, застой в малом круге, опухоль, инородное тело, табачный дым, горячий/холодный воздух, лекарства (иАПФ: до 15% на эналаприле), рефлекторные и психогенные факторы.\n- Виды: однократный; приступообразный (астма, обструктивный бронхит, курильщики); конвульсивный с репризами и рвотой (коклюш); спазматический; острый, хронический; **сухой** и **влажный (продуктивный)**.\n- Осложнения мучительного кашля: обморок, пневмоторакс, патологические переломы рёбер.\n- **Уход при сухом кашле:** лечение основного заболевания, обильное тёплое щелочное питьё («Боржоми» пополам с горячим молоком)."}},{"id":"nursing_resp1-029","heading":{"text":"Мокрота","level":2}},{"id":"nursing_resp1-030","text":{"text":"Мокрота — патологический секрет трахеи, бронхов и лёгких с примесью слюны. Объём — от нескольких мл (хронический бронхит) до 1–1,5 л (бронхоэктазы, прорыв абсцесса, гангрена лёгкого)."}},{"id":"nursing_resp1-031","table":{"caption":"","header":true,"rows":[{"cells":["Вид мокроты","Характер","Когда"]},{"cells":["Слизистая","Бесцветная, прозрачная, вязкая","Бронхит, астма"]},{"cells":["Серозная","Жидкая, пенистая","Отёк лёгких"]},{"cells":["Гнойная","С гноем","Прорыв абсцесса в бронх"]},{"cells":["Гнилостная","Гнойная с гнилостным запахом","Гангрена, абсцесс"]},{"cells":["Кровянистая","С примесью крови","Рак лёгкого"]},{"cells":["«Ржавая»","Кровянистая, ржавого цвета","Пневмония (крупозная), туберкулёз"]},{"cells":["«Жемчужная»","Опалесцирующие включения","Плоскоклеточный рак бронхов"]},{"cells":["Трёхслойная","Верхний слой пенистый, средний водянистый, нижний гнойный","Гангрена лёгкого"]},{"cells":["«Малиновое желе»","Кровь равномерно смешана","Рак лёгкого"]}]}},{"id":"nursing_resp1-032","text":{"text":"**Уход при мокроте:**"}},{"id":"nursing_resp1-033","text":{"text":"- Плевательница с плотной крышкой, на дне — 0,5% хлорамин Б (для постурального дренажа — 5% хлорамин Б на треть объёма). Ежедневно опорожнять, записав количество в температурный лист, и дезинфицировать.\n- Мокроту больных туберкулёзом сжигают или обеззараживают 2 ч сухой хлорной известью (20 г на 1 л).\n- Осматривать мокроту; **прожилки крови — сразу сообщить врачу**.\n- Научить больного: не кашлять возле здоровых, прикрывать рот, не сплёвывать на пол, собирать мокроту в плевательницу.\n- Проветривать не менее 4 раз в сутки, 18–22 °C; массаж грудной клетки, дыхательная гимнастика; достаточно жидкости."}},{"id":"nursing_resp1-034","text":{"text":"Постуральный дренаж (мокрота оттекает под действием силы тяжести; бронхит, абсцесс, бронхоэктазы), несколько раз в день:"}},{"id":"nursing_resp1-036","checklist":{"title":"Алгоритм постурального дренажа","ordered":true,"steps":["Поворачивать со спины вокруг оси на 360°, каждые 45° — глубокий выдох и прокашливание; 3–6 раз.","«Поза молящегося» (коленно-локтевая): наклоны 6–8 раз, пауза 1 мин, не более 6 циклов, 5–6 раз в день.","Лёжа на боку свешивать голову и руки с кровати («поиск тапочек») 6–8 раз, 5–6 раз в день.","Положение Квинке: ножной конец кровати на 20–30 см выше головного, по 20–30 мин с перерывом 10–15 мин."]}},{"id":"nursing_resp1-037","text":{"text":"После — удобное положение, дезинфекция мокроты и плевательницы, запись в истории болезни. Не отходит мокрота ни в одном положении — дренаж неэффективен."}},{"id":"nursing_resp1-038","heading":{"text":"Кровохарканье и лёгочное кровотечение","level":2}},{"id":"nursing_resp1-039","text":{"text":"- Кровохарканье — кровь или мокрота с кровью при кашле: бронхоэктазы, абсцесс, туберкулёз, рак, митральный стеноз, ТЭЛА, аневризма аорты, травма, аутоиммунные болезни. Ложное — из дёсен и носа. Кровохарканье — **показание к экстренной госпитализации**.\n- **Массивное кровотечение** — более 240 мл за 24–48 ч; риск аспирационной пневмонии."}},{"id":"nursing_resp1-040","table":{"caption":"","header":true,"rows":[{"cells":["Признак","Лёгочное кровотечение","Желудочное кровотечение"]},{"cells":["Цвет","Алая, пенистая","Тёмная, «кофейная гуща»"]},{"cells":["Свёртывание","Не свёртывается","Сгустки, с пищей"]},{"cells":["Реакция","Щелочная","Кислая"]},{"cells":["Как выделяется","При кашле","При рвоте"]}]}},{"id":"nursing_resp1-041","text":{"text":"**Уход:** полный покой; полусидя **с наклоном в больную сторону** (чтобы кровь не попала в здоровое лёгкое); пузырь со льдом на больную половину груди, кусочки льда глотать; противокашлевые по назначению; пища холодная полужидкая; без горячих ванны и душа; до осмотра врача не двигаться и не разговаривать. **Категорически нельзя** банки, горчичники, грелки, горячие компрессы на грудь."}},{"id":"nursing_resp1-042","heading":{"text":"Боль в грудной клетке","level":2}},{"id":"nursing_resp1-043","text":{"text":"Связана с плеврой (плеврит, пневмоторакс), усиливается при дыхании — больной дышит поверхностно. Уход: положение **на больном боку**, по назначению — горчичники, обезболивающие, противокашлевые. **При температуре выше 38 °C физиопроцедуры противопоказаны.**"}},{"id":"nursing_resp1-044","heading":{"text":"Плевральная пункция (ассистирование врачу)","level":2}},{"id":"nursing_resp1-045","text":{"text":"Цели: удалить жидкость, определить её характер, ввести лекарства (в норме в плевральной полости до 50 мл). Оснащение: шприц 20 мл с тонкой иглой 5–6 см, пункционная игла 12–14 см (просвет 1–1,5 мм) с резиновой трубкой ~15 см, электроотсос, 5% йод, 70% спирт, 0,25% прокаин, стерильные пробирки и повязка."}},{"id":"nursing_resp1-047","checklist":{"title":"Алгоритм ассистирования врачу при плевральной пункции","ordered":true,"steps":["За 15–20 мин по назначению — п/к «Сульфокамфокаин» или никетамид.","Усадить раздетого до пояса больного лицом к спинке стула: одной рукой опереться на спинку, другую (со стороны поражения) завести за голову, наклониться в здоровую сторону.","Обработать руки, стерильные маска, халат, перчатки.","Место прокола: йод → спирт → йод.","Подать врачу шприц с 0,25% прокаином: анестезия в VII–VIII межребье по лопаточной или задней подмышечной линии.","Прокол — в зоне максимальной тупости, по верхнему краю нижележащего ребра (по нижнему краю идёт сосудисто-нервный пучок); в полости — ощущение «провала».","Пробная пункция — шприц 10–20 мл; большой объём — шприц Жане или электроотсос.","Для анализа 50–100 мл — в подписанные пробирки (физико-химическое, цитологическое, бактериологическое). За раз удаляют не более 800–1200 мл — иначе быстрое смещение средостения и коллапс.","Место прокола — йод, стерильная повязка; инструменты — в дезраствор.","После пункции лежать 2 ч, сутки под наблюдением."]}},{"id":"nursing_resp1-048","heading":{"text":"Сбор мокроты","level":2}},{"id":"nursing_resp1-049","text":{"text":"- Исследования: общий анализ (количество, цвет, запах, консистенция; микроскопия — кристаллы Шарко–Лейдена и спирали Куршмана при астме, эластические волокна, атипичные клетки), бактериологическое (флора и чувствительность, микобактерии туберкулёза).\n- Техника: **в 8 ч утра натощак** почистить зубы и прополоскать рот кипячёной водой → несколько глубоких вдохов → откашлять **3–5 мл** в чистую сухую градуированную банку, закрыть крышкой → в санкомнату. Для бактериологии — стерильная ёмкость, не касаться краёв руками и ртом. **На атипичные клетки — доставить немедленно** (опухолевые клетки быстро разрушаются)."}},{"id":"nursing_resp1-050","heading":{"text":"Уход за детьми с болезнями органов дыхания","level":2}},{"id":"nursing_resp1-051","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Устаревшие приёмы — сверяйтесь со стандартом кафедры","text":"- **Инородное тело в дыхательных путях:** действующие рекомендации по первой помощи (Европейский совет по реанимации, НСР) — грудному ребёнку **5 ударов между лопатками, затем 5 толчков в грудную клетку**; ребёнку старше года — 5 ударов между лопатками, затем **5 толчков в живот** (приём Геймлиха).\n- **Банки и горчичное обёртывание** в современных клинических рекомендациях не применяются.\n- **Дезинфекция** мокроты и плевательниц хлорамином Б — нормы прошлых лет; сейчас — по СанПиН 3.3686-21 и инструкциям к дезсредствам."}},{"id":"nursing_resp1-052","text":{"text":"- **Инородное тело:** в носу — зажать свободную ноздрю и попросить высморкаться. В дыхательных путях у грудного — головой вниз, 4 удара между лопатками, затем на спину и 4 толчка в грудную клетку; старшего — животом на согнутое колено, голова вниз, постукивание по спине. Нет эффекта — искусственное дыхание, реанимация, бронхоскопия.\n- **Банки:** не раньше 7 лет; межлопаточная и подлопаточная области симметрично; не на позвоночник, область сердца, молочных желёз; кожу смазать кремом, фитиль со спиртом вводят в банку на 2–3 с; снимать через 7–10 мин, надавив на кожу сбоку; затем укутать на 30–40 мин. Противопоказаны при болезнях кожи, крови, истощении, возбуждении.\n- **Горчичники:** смочить в тёплой воде, на спину, сверху полотенце; малышам — через пелёнку; кожу проверять каждые 2–3 мин, снимать при стойком покраснении, обмыть и смазать кремом.\n- **Горчичное обёртывание:** 100 г горчицы на 2 л воды ≥ 80 °C, отстоять 3–4 мин; мокрая пелёнка от ключиц до пупка, сверху фланель и одеяло, 20–25 мин, поить; после обмыть водой 34–36 °C; через день, не более 2–3 раз.\n- Для детей раннего возраста важна свободное носовое дыхание и профилактика аспирации при срыгивании (см. раздел 1)."}}]},{"id":"nursing_resp1-s05","title":"Самоконтроль по теме","blocks":[{"id":"nursing_resp1-053","quiz":{"title":"Дыхание: нормы и наблюдение","questions":[{"text":"ЧДД новорождённого в норме:","options":["16–20 в минуту","25–35 в минуту","40–60 в минуту","80–100 в минуту"],"correct":[2],"explanation":"40–60 у новорождённого — «физиологическая одышка»."},{"text":"ЧДД взрослого в норме:","options":["16–20 в минуту","10–12 в минуту","24–30 в минуту"],"correct":[0],"explanation":"У взрослого 16–20 в минуту."},{"text":"Как отмечают ЧДД в температурном листе?","options":["Красными точками","Синими точками","Чёрными столбиками"],"correct":[1],"explanation":"Кривая дыхания — синими точками."},{"text":"Почему ЧДД считают незаметно для больного?","options":["Больной может произвольно изменить частоту дыхания","Так быстрее","Чтобы не заразиться"],"correct":[0],"explanation":"Дыхание подчиняется воле; заметив подсчёт, пациент начинает дышать иначе."},{"text":"Почему инородные тела у детей чаще попадают в правый бронх?","options":["С возрастом правый бронх становится продолжением трахеи","Правый бронх уже левого","Левый бронх закрыт надгортанником"],"correct":[0],"explanation":"У малышей углы отхождения одинаковы, с возрастом правый бронх — продолжение трахеи."}]}},{"id":"nursing_resp1-054","quiz":{"title":"Симптомы и уход","questions":[{"text":"Положение пациента при кровохарканье:","options":["Лёжа на здоровом боку","Полусидя с наклоном в больную сторону","Лёжа на спине"],"correct":[1],"explanation":"Чтобы кровь не попала в здоровое лёгкое."},{"text":"Что категорически нельзя при лёгочном кровотечении?","options":["Банки и горчичники","Грелку на грудь","Пузырь со льдом на больную половину груди"],"correct":[0,1],"explanation":"Тепло усиливает кровотечение."},{"text":"Признак лёгочного кровотечения (в отличие от желудочного):","options":["Алая пенистая кровь при кашле","«Кофейная гуща»","Кислая реакция"],"correct":[0],"explanation":"Лёгочная кровь алая, пенистая, не свёртывается, щелочная."},{"text":"Положение пациента при боли в грудной клетке от плевры:","options":["На больном боку","На здоровом боку","Сидя с наклоном вперёд"],"correct":[0],"explanation":"Ограничивается подвижность поражённой стороны, боль меньше."},{"text":"Сколько мокроты собирают на общий анализ?","options":["0,5 мл","3–5 мл","50 мл"],"correct":[1],"explanation":"Утром натощак, после чистки зубов и полоскания рта."}]}}]}]}$json$::jsonb AS j) v
WHERE NOT EXISTS (SELECT 1 FROM "library_manuals" WHERE "discipline" = 'Сестринское дело' AND "title" = 'Дыхание: конспект по трём учебникам');
