INSERT INTO "library_manuals" ("discipline", "title", "specialty", "course", "semester", "authors", "annotation", "status", "draft", "published", "draft_changed", "updated_by", "created_at", "updated_at", "published_at")
SELECT 'Сестринское дело', 'Методика наблюдения и ухода при заболеваниях органов дыхания. Оксигенотерапия', 'Сестринское дело', 0, 0, 'Кафедра сестринского дела с курсом социальных дисциплин', 'Выжимка из учебного пособия «Общий уход за больными в терапевтической клинике» (с. 111, 119, 143–153) с особенностями у детей по учебникам педиатрии. Акцент на методике: подсчёт ЧДД, помощь при удушье и карманный ингалятор, уход при мокроте и постуральный дренаж, сбор мокроты, помощь при кровохарканье, ассистирование при плевральной пункции, подача кислорода через носовой катетер и из подушки — с оснащением, алгоритмами, типичными ошибками, ситуационными задачами и самоконтролем.', 2, j, j, false, 'seed', now(), now(), now()
FROM (SELECT $json${"sections":[{"id":"nursing_resp3-s01","title":"Методические указания","blocks":[{"id":"nursing_resp3-001","text":{"text":"Выжимка из учебного пособия «Общий уход за больными в терапевтической клинике»: наблюдение и уход при болезнях органов дыхания, оксигенотерапия (с. 143–153), плевральная пункция (с. 111), исследование мокроты (с. 119). Особенности у детей — по учебникам Запруднова — Григорьева (2011) и Ежовой (2014). Акцент — на **методике**: что и в каком порядке делает медсестра, зачем нужен каждый шаг и как оценить результат."}},{"id":"nursing_resp3-002","heading":{"text":"Цель занятия","level":2}},{"id":"nursing_resp3-003","text":{"text":"Освоить методику сестринского наблюдения и ухода при заболеваниях органов дыхания и методику оксигенотерапии."}},{"id":"nursing_resp3-004","heading":{"text":"Студент должен","level":2}},{"id":"nursing_resp3-005","text":{"text":"**Знать:** ЧДД по возрасту и у взрослого; виды одышки и патологические типы дыхания; виды мокроты; признаки лёгочного кровотечения; показания, концентрации и способы подачи кислорода; технику безопасности при работе с кислородом."}},{"id":"nursing_resp3-006","text":{"text":"**Уметь:**\n- подсчитать ЧДД у взрослого и ребёнка, записать в температурный лист;\n- оказать помощь при приступе удушья, обучить пациента пользоваться карманным ингалятором;\n- организовать уход при мокроте, провести постуральный дренаж, собрать мокроту;\n- оказать помощь при кровохарканье;\n- подготовить оснащение и ассистировать врачу при плевральной пункции;\n- подать увлажнённый кислород через носовой катетер и из кислородной подушки."}},{"id":"nursing_resp3-007","heading":{"text":"Схема ответа по манипуляции","level":2}},{"id":"nursing_resp3-008","checklist":{"title":"Каждая манипуляция разобрана по этой схеме","ordered":true,"steps":["Цель — зачем выполняют.","Показания и противопоказания.","Оснащение.","Подготовка пациента: объяснить ход, получить согласие, придать положение.","Алгоритм — по шагам, с обоснованием.","Оценка результата и запись (температурный лист, история болезни).","Типичные ошибки и безопасность."]}},{"id":"nursing_resp3-009","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Нормы учебников, которые устарели","text":"- **Дезинфекция** мокроты и плевательниц хлорамином Б — нормы прошлых лет; сейчас — по СанПиН 3.3686-21 и инструкциям к дезсредствам.\n- **Карбоген, спиртовые пеногасители, кислородная подушка** — приёмы прошлых лет; сейчас дозу кислорода подбирают под контролем **пульсоксиметрии (SpO₂)**.\n- **Инородное тело у ребёнка, банки, горчичное обёртывание** — см. выноску в теме «Уход за детьми».\n\nОтвечайте по стандарту кафедры."}},{"id":"nursing_resp3-010","glossary":{"terms":[{"term":"Одышка (диспноэ)","definition":"нарушение частоты, ритма и глубины дыхания с ощущением нехватки воздуха."},{"term":"Тахипноэ","definition":"учащённое поверхностное дыхание, более 20 в минуту у взрослого."},{"term":"Брадипноэ","definition":"урежение дыхания, менее 16 в минуту у взрослого."},{"term":"Удушье (астма)","definition":"острый приступ одышки: бронхиальная (спазм бронхов) или сердечная (застой в малом круге)."},{"term":"Мокрота","definition":"патологический секрет трахеи, бронхов и лёгких с примесью слюны."},{"term":"Постуральный дренаж","definition":"отток мокроты под действием силы тяжести в определённых положениях тела."},{"term":"Положение Квинке","definition":"ножной конец кровати поднят на 20–30 см выше головного."},{"term":"Оксигенотерапия","definition":"применение кислорода с лечебной целью: устраняет или уменьшает артериальную гипоксемию."},{"term":"Аппарат Боброва","definition":"увлажнитель: кислород пропускают через стерильную воду."}]}}]},{"id":"nursing_resp3-s02","title":"Подсчёт частоты дыхательных движений","blocks":[{"id":"nursing_resp3-011","table":{"caption":"","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цель","Оценить частоту, ритм и глубину дыхания"]},{"cells":["Оснащение","Часы с секундной стрелкой, температурный лист, синяя ручка; детям — фонендоскоп"]},{"cells":["Норма","Взрослый 16–20 в минуту; новорождённый 40–60; 1–12 мес 30–45; 1–3 года 25–35; 4–6 лет 23–25; 7–11 лет 18–23; 12–15 лет 17–19"]}]}},{"id":"nursing_resp3-012","checklist":{"title":"Алгоритм подсчёта ЧДД у взрослого","ordered":true,"steps":["Взять руку пациента, как для исследования пульса, — чтобы он не догадался, что считают дыхание.","Наблюдать за движениями грудной клетки (или положить руку на грудную клетку или живот).","Подсчитать число дыхательных движений за минуту.","Оценить ритм и глубину дыхания.","Записать результат в температурный лист синими точками (кривая дыхания)."]}},{"id":"nursing_resp3-013","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"Дыхание подчиняется воле: если пациент знает, что считают дыхание, он невольно меняет его частоту и глубину. Поэтому ЧДД считают **незаметно**, «под видом» исследования пульса."}},{"id":"nursing_resp3-014","text":{"text":"**У детей** считают лучше во сне: рука на животе или фонендоскоп у носа. Соотношение ЧДД : ЧСС — у новорождённых 1 : (2,5–3), у детей 1 : (3,5–4), у взрослых 1 : 4. В первые 2–3 недели жизни норма — аритмия дыхания и кратковременные апноэ 10–30 с."}},{"id":"nursing_resp3-015","table":{"caption":"","header":true,"rows":[{"cells":["Отклонение","Что это","Когда бывает"]},{"cells":["Тахипноэ","> 20 в минуту, поверхностное","Пневмония, лихорадка, анемия"]},{"cells":["Брадипноэ","< 16 в минуту","Поражение мозга, тяжёлая гипоксия, диабетическая кома"]},{"cells":["Чейна–Стокса","Нарастание и убывание глубины дыхания после паузы до 30 с","—"]},{"cells":["Биота","Равномерные глубокие вдохи чередуются с паузами до 30 с","—"]},{"cells":["Куссмауля","Глубокое редкое шумное дыхание","Глубокая кома"]}]}}]},{"id":"nursing_resp3-s03","title":"Помощь при удушье. Карманный ингалятор","blocks":[{"id":"nursing_resp3-016","text":{"text":"Удушье — бронхиальная астма (спазм бронхов) или сердечная астма (застой в малом круге)."}},{"id":"nursing_resp3-017","checklist":{"title":"Алгоритм помощи при приступе удушья","ordered":true,"steps":["Немедленно сообщить врачу.","Создать покой, успокоить больного и окружающих.","Придать возвышенное (полусидячее) положение.","Освободить от стесняющей одежды и тяжёлых одеял.","Открыть форточку.","По назначению врача — карманный ингалятор; при дыхательной недостаточности — оксигенотерапия."]}},{"id":"nursing_resp3-018","checklist":{"title":"Алгоритм пользования карманным ингалятором (обучение пациента)","ordered":true,"steps":["Снять колпачок.","Перевернуть баллончик дном вверх и встряхнуть.","Сделать глубокий выдох.","Обхватить мундштук губами и сделать глубокий вдох, одновременно нажав на клапан.","Задержать дыхание на несколько секунд.","Вынуть мундштук, медленно выдохнуть.","После ингаляции глюкокортикоидов прополоскать рот."]}},{"id":"nursing_resp3-019","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- **Глубокий выдох перед ингаляцией** — чтобы на вдохе лекарство прошло глубже в бронхи.\n- **Нажатие одновременно со вдохом** — иначе аэрозоль осядет во рту.\n- **Задержка дыхания** — лекарство успевает осесть в бронхах.\n- **Полоскание рта** после глюкокортикоидов — профилактика кандидоза.\n- Число доз определяет **врач**."}}]},{"id":"nursing_resp3-s04","title":"Мокрота: уход, постуральный дренаж, сбор на исследование","blocks":[{"id":"nursing_resp3-020","heading":{"text":"Уход при мокроте","level":2}},{"id":"nursing_resp3-021","text":{"text":"- Плевательница с плотной крышкой; ежедневно опорожнять, **записывать количество мокроты в температурный лист**, дезинфицировать.\n- Осматривать мокроту; **прожилки крови — сразу сообщить врачу**.\n- Научить пациента: не кашлять возле здоровых, прикрывать рот, не сплёвывать на пол, собирать мокроту в плевательницу.\n- Проветривать палату не менее 4 раз в сутки, температура 18–22 °C; массаж грудной клетки, дыхательная гимнастика, достаточно жидкости.\n- При сухом кашле — обильное тёплое щелочное питьё («Боржоми» пополам с горячим молоком)."}},{"id":"nursing_resp3-022","heading":{"text":"Постуральный дренаж","level":2}},{"id":"nursing_resp3-023","text":{"text":"Показания: бронхит, абсцесс лёгкого, бронхоэктазы. Проводят несколько раз в день."}},{"id":"nursing_resp3-024","checklist":{"title":"Алгоритм постурального дренажа","ordered":true,"steps":["Поворачивать пациента со спины вокруг оси на 360°; каждые 45° — глубокий выдох и прокашливание; 3–6 раз.","«Поза молящегося» (коленно-локтевая): наклоны 6–8 раз, пауза 1 мин, не более 6 циклов, 5–6 раз в день.","Лёжа на боку свешивать голову и руки с кровати («поиск тапочек») 6–8 раз, 5–6 раз в день.","Положение Квинке: ножной конец кровати на 20–30 см выше головного, по 20–30 мин с перерывом 10–15 мин.","После дренажа — удобное положение, дезинфекция мокроты и плевательницы, запись в истории болезни."]}},{"id":"nursing_resp3-025","callout":{"tone":"MANUAL_CALLOUT_TONE_CLINICAL","title":"Оценка результата","text":"Мокрота отходит — дренаж эффективен, записать количество. **Не отходит ни в одном положении — дренаж неэффективен**, сообщить врачу."}},{"id":"nursing_resp3-026","heading":{"text":"Сбор мокроты","level":2}},{"id":"nursing_resp3-027","checklist":{"title":"Алгоритм сбора мокроты на общий анализ","ordered":true,"steps":["Накануне объяснить пациенту порядок сбора.","В 8 ч утра натощак пациент чистит зубы и полощет рот кипячёной водой.","Делает несколько глубоких вдохов и откашливает 3–5 мл мокроты в чистую сухую градуированную банку.","Закрыть банку крышкой, оформить направление.","Доставить в санитарную комнату для отправки в лабораторию."]}},{"id":"nursing_resp3-028","text":{"text":"- **Бактериологическое исследование** — стерильная ёмкость; не касаться её краёв руками и ртом.\n- **На атипичные клетки** — доставить немедленно: опухолевые клетки быстро разрушаются."}},{"id":"nursing_resp3-029","table":{"caption":"","header":true,"rows":[{"cells":["Ошибка","Что получится"]},{"cells":["Мокрота собрана без чистки зубов и полоскания рта","В пробу попадает флора полости рта, остатки пищи"]},{"cells":["В банку сплюнута слюна вместо мокроты","Анализ неинформативен"]},{"cells":["Пациент коснулся краёв стерильной ёмкости","Загрязнение пробы для бактериологии"]},{"cells":["Проба на атипичные клетки долго стояла","Опухолевые клетки разрушились"]}]}}]},{"id":"nursing_resp3-s05","title":"Кровохарканье и лёгочное кровотечение","blocks":[{"id":"nursing_resp3-030","text":{"text":"Кровохарканье — **показание к экстренной госпитализации**. Массивное кровотечение — более 240 мл за 24–48 ч; опасно аспирационной пневмонией."}},{"id":"nursing_resp3-031","table":{"caption":"","header":true,"rows":[{"cells":["Признак","Лёгочное кровотечение","Желудочное кровотечение"]},{"cells":["Цвет","Алая, пенистая","Тёмная, «кофейная гуща»"]},{"cells":["Свёртывание","Не свёртывается","Сгустки, с пищей"]},{"cells":["Реакция","Щелочная","Кислая"]},{"cells":["Как выделяется","При кашле","При рвоте"]}]}},{"id":"nursing_resp3-032","checklist":{"title":"Алгоритм помощи при кровохарканье","ordered":true,"steps":["Немедленно сообщить врачу.","Обеспечить полный покой: до осмотра врача не двигаться и не разговаривать.","Усадить полусидя с наклоном в больную сторону.","Положить пузырь со льдом на больную половину грудной клетки; давать глотать кусочки льда.","Противокашлевые средства — по назначению врача.","Кормить холодной полужидкой пищей; горячие ванны и душ исключить."]}},{"id":"nursing_resp3-033","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Категорически нельзя","text":"Банки, горчичники, грелки, горячие компрессы на грудь — тепло усиливает кровотечение."}},{"id":"nursing_resp3-034","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему наклон в больную сторону","text":"Кровь стекает в поражённое лёгкое и **не попадает в здоровое** — так сохраняется дыхание и снижается риск аспирационной пневмонии."}}]},{"id":"nursing_resp3-s06","title":"Плевральная пункция: ассистирование врачу","blocks":[{"id":"nursing_resp3-035","table":{"caption":"","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цели","Удалить жидкость, определить её характер, ввести лекарства (в норме в плевральной полости до 50 мл)"]},{"cells":["Оснащение","Шприц 20 мл с тонкой иглой 5–6 см, пункционная игла 12–14 см (просвет 1–1,5 мм) с резиновой трубкой около 15 см, шприц Жане или электроотсос, 5% йод, 70% спирт, 0,25% прокаин, стерильные пробирки, стерильная повязка, стерильные маска, халат, перчатки"]},{"cells":["Положение","Сидя на стуле лицом к спинке, раздетый до пояса; одной рукой опирается на спинку, другую (со стороны поражения) заводит за голову, наклоняется в здоровую сторону"]}]}},{"id":"nursing_resp3-036","checklist":{"title":"Алгоритм ассистирования врачу при плевральной пункции","ordered":true,"steps":["За 15–20 мин по назначению врача ввести подкожно препарат («Сульфокамфокаин» или никетамид).","Усадить пациента лицом к спинке стула, рука со стороны поражения заведена за голову, наклон в здоровую сторону.","Обработать руки, надеть стерильные маску, халат, перчатки.","Обработать место прокола: йод → спирт → йод.","Подать врачу шприц с 0,25% прокаином для анестезии в VII–VIII межреберье по лопаточной или задней подмышечной линии.","Подать пункционную иглу; при большом объёме подготовить шприц Жане или электроотсос.","Собрать 50–100 мл жидкости в подписанные пробирки: физико-химическое, цитологическое, бактериологическое исследование.","Следить за состоянием пациента во время пункции.","Место прокола обработать йодом, наложить стерильную повязку; инструменты — в дезраствор.","Уложить пациента на 2 ч; наблюдать в течение суток."]}},{"id":"nursing_resp3-037","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- **Рука за голову и наклон в здоровую сторону** — межреберья расширяются.\n- **Прокол по верхнему краю нижележащего ребра** — по нижнему краю ребра идёт сосудисто-нервный пучок.\n- **За раз не более 800–1200 мл** — быстрое удаление большого объёма смещает средостение, возможен коллапс."}}]},{"id":"nursing_resp3-s07","title":"Оксигенотерапия","blocks":[{"id":"nursing_resp3-038","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Три правила","text":"1. **Перед подачей кислорода — проходимость дыхательных путей**: туалет полости рта, воздуховод, санация.\n2. **Кислород всегда увлажняют**: аппарат Боброва или влажная марля на мундштуке.\n3. **Минимальная эффективная концентрация**; чистый кислород длительно не дают — угнетает дыхательный центр, обжигает дыхательные пути, токсичен."}},{"id":"nursing_resp3-039","text":{"text":"**Показания:** острая или хроническая дыхательная недостаточность с цианозом, тахикардией, снижением парциального давления кислорода; тяжёлая одышка, особенно в покое. У детей — гипоксия любого происхождения, кроме гистотоксической. Концентрация: взрослым — 40–80%; длительная непрерывная оксигенотерапия — 24–44%."}},{"id":"nursing_resp3-040","table":{"caption":"","header":true,"rows":[{"cells":["Способ","Концентрация O₂","Когда"]},{"cells":["Носовой катетер, канюли","До 40–60%","Основной способ; у детей — двойные мягкие канюли"]},{"cells":["Лицевая маска","20–60%, при тяжёлой гипоксии до 80–100%","Тяжёлая гипоксия"]},{"cells":["Палатка, тент, колпак","До 65%","Дети: круп, обструктивный бронхит"]},{"cells":["ИВЛ через интубационную трубку","До 100%","Нет или неэффективно самостоятельное дыхание"]},{"cells":["Кислородная подушка","Стойкой концентрации не даёт","Дома, когда нет баллона"]}]}},{"id":"nursing_resp3-041","heading":{"text":"Подача кислорода через носовой катетер","level":2}},{"id":"nursing_resp3-042","text":{"text":"**Оснащение:** кислородный баллон или централизованная подача, стерильные носовые катетеры, стерильный вазелин (детям — глицерин), трубка, пластырь, аппарат Боброва со стерильной водой."}},{"id":"nursing_resp3-043","checklist":{"title":"Алгоритм подачи кислорода через носовой катетер","ordered":true,"steps":["Убедиться в проходимости дыхательных путей, объяснить пациенту ход процедуры.","Измерить глубину введения: от крыла носа до мочки (козелка) уха.","Смазать стерильный катетер вазелином (детям — глицерином).","Ввести катетер по нижнему носовому ходу до задней стенки глотки на отмеренную глубину.","Если пациент в сознании — попросить открыть рот: конец катетера должен быть виден в зеве.","Соединить наружный конец с трубкой системы подачи кислорода, закрепить пластырем к щеке.","Открыть вентиль дозиметра, подавать кислород 2–3 л/мин, увлажняя через аппарат Боброва.","Каждые 30–60 мин менять положение катетера."]}},{"id":"nursing_resp3-044","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- Конец катетера — **на 1 см ниже язычка мягкого нёба**: выше — меньше кислорода во вдыхаемом воздухе, ниже — кислород идёт в пищевод, аэрофагия и растяжение желудка.\n- **Детям — глицерин**: меньше раздражает слизистую.\n- **Смена положения каждые 30–60 мин** — профилактика пролежней и пересыхания слизистой."}},{"id":"nursing_resp3-045","heading":{"text":"Подача кислорода из кислородной подушки","level":2}},{"id":"nursing_resp3-046","checklist":{"title":"Алгоритм подачи кислорода из кислородной подушки","ordered":true,"steps":["Снять мундштук, открыть кран подушки, соединить трубку с редуктором баллона; стоя сбоку от баллона, медленно открыть вентиль и наполнить подушку.","Закрыть кран редуктора и вентиль подушки.","Обработать мундштук салфеткой с 70% спиртом.","Объяснить пациенту: вдох через рот, выдох через нос.","Обернуть мундштук 2–3 слоями стерильной марли, смоченной водой.","Вставить мундштук в рот, медленно открыть кран.","Регулировать подачу нажатием на подушку; по мере опорожнения сворачивать её с угла, противоположного мундштуку."]}},{"id":"nursing_resp3-047","text":{"text":"Подушки на 10–25 л хватает на 5–7 мин; стойкой концентрации кислорода она не даёт."}},{"id":"nursing_resp3-048","heading":{"text":"Техника безопасности","level":2}},{"id":"nursing_resp3-049","table":{"caption":"","header":true,"rows":[{"cells":["Правило","Почему"]},{"cells":["Стоять сбоку от баллона при открытии вентиля","Струя может повредить глаза"]},{"cells":["Не смазывать руки кремом, рядом нет промасленной ветоши и свежей краски","Сжатый кислород с жирами и нефтепродуктами воспламеняется и взрывается"]},{"cells":["Не курить, не ставить баллон у источников тепла","Риск возгорания"]},{"cells":["Стерильные катетеры, канюли и вода в увлажнителе","Профилактика инфекции"]}]}},{"id":"nursing_resp3-050","text":{"text":"Баллон: 40 л, 150 атм, **синий** с надписью «Кислород медицинский»; пациенту кислород подают под давлением 2–3 атм через редуктор."}},{"id":"nursing_resp3-051","heading":{"text":"Особенности у детей","level":2}},{"id":"nursing_resp3-052","text":{"text":"- **В кувезе** — около 30% увлажнённого кислорода; минимальная концентрация, при которой исчезают цианоз, вялость, апноэ, брадикардия.\n- **Круп** — тент или кислородная палатка с высокой влажностью и аэрозолями.\n- **Астматический статус** — увлажнённый кислород сеансами по 30 мин с перерывом 30 мин.\n- **Обструктивный бронхит** — успокоить, кислород под тентом или через носовой катетер, тёплое питьё."}}]},{"id":"nursing_resp3-s08","title":"Уход за детьми с болезнями органов дыхания","blocks":[{"id":"nursing_resp3-053","text":{"text":"- Для детей раннего возраста важно **свободное носовое дыхание**: новорождённый дышит только носом, даже лёгкий насморк затрудняет сосание и вызывает одышку.\n- **Профилактика аспирации** при срыгивании: надгортанник мягкий и неплотно закрывает трахею.\n- **Инородное тело в носу** — зажать свободную ноздрю и попросить высморкаться.\n- **Горчичники** — смочить в тёплой воде, положить на спину, сверху полотенце; малышам — через пелёнку; кожу проверять каждые 2–3 мин, снять при стойком покраснении, обмыть и смазать кремом."}},{"id":"nursing_resp3-054","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Инородное тело в дыхательных путях — по действующим рекомендациям","text":"Учебник даёт: грудному — головой вниз, 4 удара между лопатками, затем 4 толчка в грудную клетку; старшего — животом на колено, постукивание по спине. Действующие рекомендации по первой помощи (Европейский совет по реанимации, НСР): грудному ребёнку — **5 ударов между лопатками, затем 5 толчков в грудную клетку**; ребёнку старше года — **5 ударов между лопатками, затем 5 толчков в живот** (приём Геймлиха). Нет эффекта — реанимация, вызов помощи. Банки и горчичное обёртывание в современных рекомендациях не применяются. Отвечайте по стандарту кафедры."}}]},{"id":"nursing_resp3-s09","title":"Ситуационные задачи","blocks":[{"id":"nursing_resp3-055","text":{"text":"Решите задачу письменно по схеме: проблемы пациента → что делает медсестра (по шагам) → обоснование. Затем сверьтесь с эталоном."}},{"id":"nursing_resp3-056","clinicalCase":{"title":"Задача 1. Ночной приступ","condition":"Пациентка 34 лет с бронхиальной астмой ночью проснулась от удушья: сидит, опираясь руками о кровать, выдох затруднён и удлинён, слышны свистящие хрипы. В тумбочке — карманный ингалятор, назначенный врачом.","questions":["Какой вид одышки у пациентки?","Составьте алгоритм помощи.","Как пациентка должна пользоваться ингалятором?"],"answer":"**Экспираторная одышка** — затруднён выдох (спазм бронхов).\n\nСообщить врачу; успокоить пациентку и соседей по палате; придать полусидячее положение; освободить от стесняющей одежды и тяжёлого одеяла; открыть форточку; по назначению — ингалятор, при дыхательной недостаточности — увлажнённый кислород.\n\nИнгалятор: снять колпачок, перевернуть дном вверх и встряхнуть, глубокий выдох, обхватить мундштук губами и на глубоком вдохе нажать на клапан, задержать дыхание на несколько секунд, медленный выдох; после глюкокортикоидов — прополоскать рот."}},{"id":"nursing_resp3-057","clinicalCase":{"title":"Задача 2. Кровь при кашле","condition":"Пациент 58 лет с туберкулёзом лёгких (поражено правое лёгкое) при кашле выделил около 50 мл алой пенистой крови. Испуган, пытается встать и пойти к врачу.","questions":["Как отличить лёгочное кровотечение от желудочного?","Какое положение придать и почему?","Что медсестра делает и чего делать нельзя?"],"answer":"Лёгочное: кровь **алая, пенистая, не свёртывается, щелочная, выделяется при кашле**; желудочное — тёмная, «кофейная гуща», сгустки, кислая, при рвоте.\n\n**Полусидя с наклоном вправо** (в больную сторону) — чтобы кровь не попала в здоровое левое лёгкое.\n\nСрочно сообщить врачу; полный покой — не вставать и не разговаривать; пузырь со льдом на правую половину груди, глотать кусочки льда; противокашлевые — по назначению; пища холодная полужидкая. **Нельзя:** банки, горчичники, грелки, горячие компрессы. Мокроту больного туберкулёзом собирать в плевательницу и обеззараживать."}},{"id":"nursing_resp3-058","clinicalCase":{"title":"Задача 3. Носовой катетер","condition":"Медсестра ввела пациенту носовой катетер на 4 см и подаёт сухой кислород со скоростью 6 л/мин. Через 2 ч пациент жалуется на сухость и жжение в носу, вздутие живота.","questions":["Какие ошибки допущены?","Чем объясняются жалобы?","Опишите правильную методику."],"answer":"**Ошибки:** глубина не отмерена; кислород не увлажнён; поток больше 2–3 л/мин; положение катетера не меняли.\n\nСухой кислород и неподвижный катетер вызывают пересыхание слизистой; при неправильном положении конца катетера кислород идёт в пищевод — аэрофагия, растяжение желудка.\n\n**Правильно:** проверить проходимость дыхательных путей; отмерить глубину от крыла носа до мочки уха; смазать катетер стерильным вазелином; ввести по нижнему носовому ходу, конец виден в зеве (на 1 см ниже язычка); закрепить пластырем; подавать 2–3 л/мин через аппарат Боброва со стерильной водой; каждые 30–60 мин менять положение катетера."}},{"id":"nursing_resp3-059","clinicalCase":{"title":"Задача 4. Плевральная пункция","condition":"Пациенту с экссудативным плевритом справа назначена плевральная пункция. Врач просит медсестру подготовить пациента и ассистировать.","questions":["Как усадить пациента?","Где проводят прокол и почему по верхнему краю ребра?","Сколько жидкости можно удалить за одну пункцию?","Что делать после пункции?"],"answer":"Сидя на стуле **лицом к спинке**, раздетым до пояса; левой рукой опирается на спинку, **правую заводит за голову**, наклоняется влево (в здоровую сторону) — межреберья расширяются.\n\nАнестезия и прокол — в **VII–VIII межреберье по лопаточной или задней подмышечной линии**, в зоне максимальной тупости, **по верхнему краю нижележащего ребра**: по нижнему краю ребра идёт сосудисто-нервный пучок.\n\nНе более **800–1200 мл** за раз — иначе быстрое смещение средостения и коллапс. 50–100 мл — в подписанные пробирки на исследования.\n\nМесто прокола — йод, стерильная повязка; пациент лежит **2 ч**, наблюдение в течение суток."}},{"id":"nursing_resp3-060","clinicalCase":{"title":"Задача 5. Ребёнок с одышкой","condition":"Ребёнку 2 лет медсестра насчитала 52 дыхания в минуту, пока он плакал на руках у мамы. Мама волнуется, что у ребёнка «сильная одышка».","questions":["Правильно ли подсчитана ЧДД?","Какая ЧДД нормальна в этом возрасте?","Как правильно считать дыхание у ребёнка раннего возраста?"],"answer":"Нет: при плаче дыхание учащается, результат недостоверен.\n\nВ 1–3 года норма — **25–35 в минуту**; соотношение ЧДД : ЧСС у детей 1 : (3,5–4).\n\nСчитать лучше **во сне** (или в спокойном состоянии): рука на животе — у малышей брюшной (диафрагмальный) тип дыхания — или фонендоскоп у носа. Записать в температурный лист синими точками; при сохраняющемся учащении — сообщить врачу."}}]},{"id":"nursing_resp3-s10","title":"Самоконтроль","blocks":[{"id":"nursing_resp3-061","quiz":{"title":"Методика ухода при заболеваниях органов дыхания","questions":[{"text":"С чего начинают помощь при приступе удушья?","options":["Сообщить врачу и придать полусидячее положение","Поставить горчичники","Уложить на спину без подушки"],"correct":[0],"explanation":"Затем — покой, освободить от стесняющей одежды, открыть форточку, лекарства по назначению."},{"text":"Когда нажимают на клапан карманного ингалятора?","options":["На выдохе","Одновременно с глубоким вдохом","После задержки дыхания"],"correct":[1],"explanation":"Иначе аэрозоль осядет во рту."},{"text":"Положение Квинке — это:","options":["Ножной конец кровати на 20–30 см выше головного","Коленно-локтевое положение","Полусидячее положение"],"correct":[0],"explanation":"Одно из положений постурального дренажа."},{"text":"Когда доставляют мокроту на атипичные клетки?","options":["В течение суток","Немедленно","На следующее утро"],"correct":[1],"explanation":"Опухолевые клетки быстро разрушаются."},{"text":"По какому краю ребра прокалывают при плевральной пункции?","options":["По верхнему краю нижележащего ребра","По нижнему краю вышележащего ребра","Посередине межреберья, независимо от рёбер"],"correct":[0],"explanation":"По нижнему краю ребра проходит сосудисто-нервный пучок."},{"text":"Сколько жидкости удаляют за одну плевральную пункцию?","options":["Всю, сколько есть","Не более 800–1200 мл","Не более 100 мл"],"correct":[1],"explanation":"Быстрое удаление большого объёма смещает средостение, возможен коллапс."}]}},{"id":"nursing_resp3-062","quiz":{"title":"Оксигенотерапия","questions":[{"text":"Где должен находиться конец носового катетера?","options":["На 1 см ниже язычка мягкого нёба, виден в зеве","В преддверии носа","В пищеводе"],"correct":[0],"explanation":"Выше — мало кислорода, ниже — аэрофагия."},{"text":"Чем увлажняют кислород?","options":["Аппаратом Боброва со стерильной водой","Не увлажняют","Водопроводной водой в банке"],"correct":[0],"explanation":"Вода в увлажнителе — стерильная."},{"text":"Перед подачей кислорода нужно:","options":["Убедиться в проходимости дыхательных путей","Дать пациенту поесть","Уложить пациента на живот"],"correct":[0],"explanation":"Туалет полости рта, воздуховод, санация."},{"text":"Какое дыхание нужно объяснить пациенту при подаче кислорода из подушки?","options":["Вдох через рот, выдох через нос","Вдох через нос, выдох через рот","Задержка дыхания на вдохе"],"correct":[0],"explanation":"Мундштук во рту, кислород поступает на вдохе."},{"text":"Концентрация кислорода в кувезе у новорождённого:","options":["100%","около 30%","60–80%"],"correct":[1],"explanation":"Минимальная, при которой исчезают признаки гипоксемии."}]}}]}]}$json$::jsonb AS j) v
